script:
frappe.ui.form.on('IPD', {
    refresh: function(frm) {
        if (frm.doc.ward) {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Ward Room",
                    filters: { ward: frm.doc.ward },
                    fields: ["room_no"],
                    limit_page_length: 100
                },
                callback: function(r) {
                    if (r.message) {
                        let room_no_options = r.message.map(d => d.room_no);
                        frm.set_df_property('room_no', 'options', room_no_options.join('\n'));
                        frm.refresh_field('room_no');
                    }
                }
            });
        }

        frappe.call({
            method: 'frappe.client.get_value',
            args: {
                doctype: 'User',
                filters: { name: frappe.session.user },
                fieldname: 'full_name'
            },
            callback: function(response) {
                if (response.message) {
                    let full_name = response.message.full_name;

                    let html_content = `
                        <div style="font-size: 35px; color: #A0522D; font-family: Tahoma;">
                            <center>
                                <img src="/files/personnel.png" style="width: 80px; height: 80px; margin-right: 10px;">
                                <span>User Login: ${full_name}</span>
                            </center>
                        </div>
                    `;
                    frm.set_df_property('html_display_user', 'options', html_content);
                }
            }
        });
    },
    ward: function(frm) {
        if (frm.doc.ward) {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Ward Room",
                    filters: { ward: frm.doc.ward },
                    fields: ["room_no"],
                    limit_page_length: 100
                },
                callback: function(r) {
                    if (r.message) {
                        let room_no_options = r.message.map(d => d.room_no);
                        frm.set_df_property('room_no', 'options', room_no_options.join('\n'));
                        frm.refresh_field('room_no');
                    }
                }
            });
        } else {
            frm.set_value('room_no', "");
        }
    }
});

frappe.ui.form.on("IPD", {
    setup: function(frm) {
        frm.set_query("doctor_name", function() {
            return {
                filters: { "department": "แพทย์" }
            };
        });
    }
});

frappe.ui.form.on('IPD', {
    before_save: function(frm) {
        var no = frm.doc.no || "";
        var moo = frm.doc.moo ? 'ม.' + frm.doc.moo : "";
        var road = frm.doc.road ? 'ถ.' + frm.doc.road : "";
        var tambon = frm.doc.tambon || "";
        var amphoe = frm.doc.amphoe || "";
        var province = frm.doc.province || "";
        var postal_code = frm.doc.postal_code || "";

        var address = no + " " + moo;
        if (road) { address += " " + road; }

        if (province === 'กรุงเทพมหานคร') {
            address += " " + tambon;
            if (amphoe) { address += ' เขต' + amphoe; }
            address += " " + province + " " + postal_code;
        } else {
            if (tambon) { address += ' ต.' + tambon; }
            if (amphoe) { address += ' อ.' + amphoe; }
            if (province) { address += ' จ.' + province; }
            address += " " + postal_code;
        }

        frm.set_value('address', address.trim());
    }
});

frappe.ui.form.on('IPD', {
    after_workflow_action: function(frm) {
        if (frm.doc.wf_ipd_state === "รับผู้ป่วยเข้า Ward") {
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'User',
                    fields: ['full_name'],
                    filters: { 'name': frappe.session.user },
                    limit_page_length: 1
                },
                callback: function(response) {
                    if (response.message && response.message.length > 0) {
                        frm.set_value('fullname_ward', response.message[0].full_name);
                        frm.set_value('date_admit_ward', frappe.datetime.nowdate());
                        frm.set_value('time_admit_ward', frappe.datetime.now_time());
                        frm.save();
                    }
                }
            });
        } else if (frm.doc.wf_ipd_state === "ยกเลิก AN") {
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'User',
                    fields: ['full_name'],
                    filters: { 'name': frappe.session.user },
                    limit_page_length: 1
                },
                callback: function(response) {
                    if (response.message && response.message.length > 0) {
                        frm.set_value('cancle_date_an', frappe.datetime.nowdate());
                        frm.set_value('cancle_time_an', frappe.datetime.now_time());
                        frm.save();
                    }
                }
            });
        } else if (frm.doc.wf_ipd_state === "Discharge") {
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'User',
                    fields: ['full_name'],
                    filters: { 'name': frappe.session.user },
                    limit_page_length: 1
                },
                callback: function(response) {
                    if (response.message && response.message.length > 0) {
                        frm.set_value('fullname_discharge', response.message[0].full_name);
                        frm.set_value('discharge_date', frappe.datetime.nowdate());
                        frm.set_value('discharge_time', frappe.datetime.now_time());
                        frm.save();
                    }
                }
            });
        } 
    }
});

frappe.ui.form.on('IPD', {
    discharge_date: function(frm) { calculate_bedtime(frm); },
    date_admit_ward: function(frm) { calculate_bedtime(frm); },
    wf_ipd_state: function(frm) { calculate_bedtime(frm); }
});

function calculate_bedtime(frm) {
    if (frm.doc.wf_ipd_state === "Discharge" && frm.doc.date_admit_ward && frm.doc.discharge_date) {
        let admit_date = frappe.datetime.str_to_obj(frm.doc.date_admit_ward);
        let discharge_date = frappe.datetime.str_to_obj(frm.doc.discharge_date);
        let diff_days = frappe.datetime.get_day_diff(discharge_date, admit_date);
        frm.set_value('number_days_bedtime', diff_days === 0 ? 1 : diff_days);
    } else {
        frm.set_value('number_days_bedtime', 0);
    }
}

frappe.ui.form.on("IPD", {
    icd10: function(frm) {
        if (frm.doc.icd10) {
            frappe.db.get_doc("ICD 10", frm.doc.icd10).then(icd10 => {
                if (!frm.doc.icd10_detail_table) {
                    frm.doc.icd10_detail_table = [];
                }
                let exists = frm.doc.icd10_detail_table.some(row => row.procedure_code === icd10.name);
                if (!exists) {
                    let new_row = frm.add_child("icd10_detail_table");
                    new_row.procedure_code = icd10.name;
                    new_row.long_description = icd10.long_description;
                    frm.refresh_field("icd10_detail_table");
                }
                frm.set_value("icd10", "");
            });
        }
    }
});

frappe.ui.form.on('IPD', {
    or_check: function(frm) {
        frm.clear_table('or_table');
        if (frm.doc.or_check && frm.doc.hn && frm.doc.vn) {
            frappe.db.get_list('OR', {
                filters: { hn: frm.doc.hn, vn: frm.doc.vn },
                fields: ['name'],
                limit: 50
            }).then(records => {
                if (records.length > 0) {
                    records.forEach(or => {
                        let child = frm.add_child('or_table');
                        child.or = or.name;
                    });
                    frm.refresh_field('or_table');
                } else {
                    frappe.msgprint('ไม่พบข้อมูล HN และ VN นี้ใน OR');
                }
            });
        }
    }
});

frappe.ui.form.on('IPD', {
    or_check: function(frm) {
        if (!frm.doc.or_check) {
            frm.clear_table('or_table');
            frm.refresh_field('or_table');
        }
    }
});

frappe.ui.form.on('IPD', {
    refresh: function(frm) {
        let btn_color = "#28a745";
        let button_html = `
            <div style="width: 100%; text-align: center; padding: 10px 0;">
                <button class="btn btn-primary" id="btn_order_food"
                    style="background-color: ${btn_color}; border-color: ${btn_color}; padding: 15px 40px; font-size: 20px; font-weight: bold; border-radius: 10px;">
                    สั่งอาหาร
                </button>
            </div>
        `;
        $(frm.fields_dict.button_order.wrapper).html(button_html);
        $(frm.fields_dict.button_order.wrapper).find('#btn_order_food').on('click', function() {
            open_diet_slip_dialog(frm);
        });
    }
});

function calculate_all(values) {
    let weight = values.weight;
    let height = values.high;
    let age = values.age;
    let gender = values.gender;

    if (weight && height) {
        let h = height / 100;
        let bmi = weight / (h * h);
        bmi = parseFloat(bmi.toFixed(2));
        values.ipn_bmi = bmi;

        if (bmi < 18.5) {
            values.ipn_bmi_criteria = "น้ำหนักน้อยเกินไป (+)";
            values.ipn_gain_weight = 1;
            values.ipn_lose_weight = 0;
        } else if (bmi < 23) {
            values.ipn_bmi_criteria = "น้ำหนักปกติ (น้อย)";
            values.ipn_gain_weight = 0;
            values.ipn_lose_weight = 0;
        } else if (bmi < 25) {
            values.ipn_bmi_criteria = "น้ำหนักเกิน (ท้วม) (+)";
            values.ipn_gain_weight = 0;
            values.ipn_lose_weight = 1;
        } else if (bmi < 30) {
            values.ipn_bmi_criteria = "อ้วนระดับ 1 (++)";
            values.ipn_gain_weight = 0;
            values.ipn_lose_weight = 1;
        } else if (bmi < 40) {
            values.ipn_bmi_criteria = "อ้วนระดับ 2 (+++)";
            values.ipn_gain_weight = 0;
            values.ipn_lose_weight = 1;
        } else {
            values.ipn_bmi_criteria = "อ้วนระดับ 3 (++++)";
            values.ipn_gain_weight = 0;
            values.ipn_lose_weight = 1;
        }
        values.ipn_suitable_weight = parseFloat((22 * (h * h)).toFixed(2));
    }

    if (weight && height && age != null && gender) {
        let bmr = 0;
        if (gender === "เพศชาย") {
            bmr = 66.47 + (13.75 * weight) + (5 * height) - (6.75 * age);
        } else if (gender === "เพศหญิง") {
            bmr = 655.09 + (9.56 * weight) + (1.85 * height) - (4.68 * age);
        }
        values.ipn_daily_calorie_requirement = Math.round(bmr);
    }
    return values;
}

function open_diet_slip_dialog(frm, existing_row) {

    // ใช้ตัวแปร row เป็น Row เดิมตลอดทั้ง Dialog
    let row = existing_row || null;

    console.log("OPEN DIET SLIP");
    console.log("EDIT ROW:", row);
    let d = new frappe.ui.Dialog({
        fields: [
            {
                fieldtype: 'HTML',
                fieldname: 'header_html',
                options: `
                    <div style="background:#2FA084; color:white; padding:10px; border-radius:10px; text-align:center; font-size:22px; font-weight:bold;">
                        🍱 ระบบสั่งอาหารผู้ป่วย (Diet Slip)
                    </div>
                `
            },
            { fieldtype: 'Section Break' , label: 'วันที่สั่งอาหาร' }, 
            { label: 'วัน-เดือน-ปี', fieldname: 'date', fieldtype: 'Date', default: frappe.datetime.nowdate(),
                onchange: function() {
                    let date = d.get_value('date');
                    if (date) {
                        let day_names = ["วันอาทิตย์", "วันจันทร์", "วันอังคาร", "วันพุธ", "วันพฤหัสบดี", "วันศุกร์", "วันเสาร์"];
                        let js_date = new Date(date);
                        let thai_day = day_names[js_date.getDay()];
                        d.set_value('thai_day', thai_day);
                    }
                }
            },
            { label: 'เลขที่ห้องพักผู้ป่วย', fieldname: 'room_num', fieldtype: 'Data', read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'วัน', fieldname: 'thai_day', fieldtype: 'Data', read_only: 1},
            { label: 'ผู้สั่งอาหาร', fieldname: 'ordered_by', fieldtype: 'Data', default: frappe.session.user_fullname, read_only: 1, columns: 6 },
            
            { fieldtype: 'Section Break', label: 'ประวัติคนไข้' },
            { label: 'HN', fieldname: 'hn', fieldtype: 'Data', read_only: 1, columns: 6 },
            { label: 'AN', fieldname: 'an', fieldtype: "Data", read_only: 1 },
            { label: 'อายุ/ปี', fieldname: 'age', fieldtype: 'Int', read_only: 1 },
            { label: 'เพศ', fieldname: 'gender', fieldtype: 'Data', read_only: 1 },
            { label: 'โรคประจำตัว', fieldname: 'congenital_disease', fieldtype: 'MultiSelectPills',
                options: ['ถุงลมโป่งพอง', 'มะเร็ง', 'โรคหลอดเลือดหัวใจ', 'ไต', 'ไขมันในเลือดสูง', 'เบาหวาน', 'อ้วนลงพุง', 'ความดันโลหิตสูง','อื่น ๆ (ระบุ)', 'ไม่มีโรคประจำตัว' ],
                onchange: function() { toggle_specify_fields(d); }
            },
            { label: 'โปรดระบุ (มะเร็ง)', fieldname: 'specify_cancer', fieldtype: 'Data', hidden: 1 },
            { label: 'โปรดระบุ (อื่น ๆ ระบุ)', fieldname: 'specify_other', fieldtype: 'Data', hidden: 1 },
            
            { fieldtype: 'Column Break' },
            { label: 'ชื่อ-นามสกุล', fieldname: 'name', fieldtype: 'Data', read_only: 1 },
            { label: 'วัน/เดือน/ปีเกิด', fieldname: 'dob', fieldtype: 'Date' },
            { label: 'น้ำหนัก', fieldname: 'weight', fieldtype: 'Data' },
            { label: 'ส่วนสูง', fieldname: 'high', fieldtype: 'Data' },
                
            { fieldtype: 'Section Break', label: 'ข้อมูลการสั่งอาหาร' },
            { label: 'ประเภทของผู้ป่วย', fieldname: 'procedure_name', fieldtype: 'Link', 
                options: 'Diet Menu Master', 
                onchange() { load_food_menu(d); } 
            },
            
            { label: 'อาหารเช้า', fieldname: 'breakfast', fieldtype: 'Check', onchange() {toggle_meal_fields(d); load_food_menu(d);} },
            { label: 'เมนูเช้า', fieldname: 'breakfast_menu', fieldtype: 'Select', hidden: 1 },
            { label: 'อาหารเที่ยง', fieldname: 'lunch', fieldtype: 'Check', onchange() {toggle_meal_fields(d); load_food_menu(d);} },
            { label: 'เมนูเที่ยง', fieldname: 'lunch_menu', fieldtype: 'Select', hidden: 1 },
            { label: 'อาหารเย็น', fieldname: 'dinner', fieldtype: 'Check', onchange() {toggle_meal_fields(d); load_food_menu(d);} },
            { label: 'เมนูเย็น', fieldname: 'dinner_menu', fieldtype: 'Select', hidden: 1 },
            { fieldtype: 'Section Break' },
            { label: 'แพ้อาหาร', fieldname: 'is_allergic', fieldtype: 'Check', onchange: function() { toggle_food_fields(d); } },
            { label: 'โปรดระบุ (แพ้อาหาร)', fieldname: 'specify_allergy', fieldtype: 'Data', hidden: 1 },
            { label: 'งดอาหาร', fieldname: 'skip_meal', fieldtype: 'Check',
                onchange: function() {
                    toggle_food_fields(d);
                    if (d.get_value('skip_meal')) {
                        d.set_value('specify_skip', 'นมและผลิตภัณฑ์ที่ทำจากนม ทุกประเภท');
                    } else {
                        d.set_value('specify_skip', '');
                    }
                }
            },
            { label: 'โปรดระบุ (งดอาหาร)', fieldname: 'specify_skip', fieldtype: 'Data', hidden: 1, read_only: 1 },
            
            { fieldtype: 'Section Break' },
            { label: 'คำสั่งพิเศษ', fieldname: 'special_instruction', fieldtype: 'Select', 
                options: ['', 'อาหารฝรั่ง', 'อาหารไทย', 'อาหารอิสลาม', 'อาหารมังสวิรัติ'] },
        ],
        
        primary_action_label: 'ยืนยันการสั่งอาหาร',
        
        primary_action(values) {
            let procedure_link_id = values.procedure_name;

            console.log("Values to save:", values);
            values = calculate_all(values);
            
            let errors = [];
            if (!procedure_link_id) { errors.push("• กรุณาเลือกประเภทของผู้ป่วย"); }
            if (!values.breakfast && !values.lunch && !values.dinner) { errors.push("• กรุณาเลือกมื้ออาหารอย่างน้อย 1 มื้อ"); }

            if (errors.length > 0) {
                frappe.msgprint({ title: "กรอกข้อมูลไม่ครบ", indicator: "red", message: errors.join("<br>") });
                return;
            }

            let food_summary = [];
            if (values.is_allergic && values.specify_allergy) { food_summary.push("แพ้: " + values.specify_allergy); }
            if (values.skip_meal && values.specify_skip) { food_summary.push("งด: " + values.specify_skip); }
            values.ipn_food_allergy = food_summary.join(" / ");

            let meal_history = [{
                meal_date: values.date,
                breakfast_menu: values.breakfast_menu,
                lunch_menu: values.lunch_menu,
                dinner_menu: values.dinner_menu,
                ordered_by: values.ordered_by
            }];

            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Inpatient Nutrition Data Form",
                    filters: { ipn_hn_num: values.hn, ipn_an_num: values.an },
                    fields: ["name"],
                    limit_page_length: 1
                },
                callback: function(r) {
                    if (r.message && r.message.length > 0) {
                        let docname = r.message[0].name;
                        frappe.call({
                            method: "frappe.client.get",
                            args: { doctype: "Inpatient Nutrition Data Form", name: docname },
                            callback: function(res) {
                                let doc = res.message;
                                doc.ipn_food_allergy = values.ipn_food_allergy;
                                doc.ipn_get_treat_symptoms = procedure_link_id;

                                doc.meal_history_table = doc.meal_history_table || [];

                            if (row) {

                        // ==============================
                        // EDIT MODE
                        // แก้ Row เดิม ไม่สร้าง Row ใหม่
                        // ==============================

                            let meal_row = doc.meal_history_table.find(function(meal) {

                            return ( meal.meal_date === row.date_pa );
                        });

                            if (meal_row) {

                            meal_row.meal_date = values.date;
                            meal_row.breakfast_menu = values.breakfast_menu;
                            meal_row.lunch_menu = values.lunch_menu;
                            meal_row.dinner_menu = values.dinner_menu;
                            meal_row.ordered_by = values.ordered_by;

                            } else {

                            // ถ้าไม่พบจริง ๆ จึงสร้างใหม่
                            doc.meal_history_table.push({
                            meal_date: values.date,
                            breakfast_menu: values.breakfast_menu,
                            lunch_menu: values.lunch_menu,
                            dinner_menu: values.dinner_menu,
                            ordered_by: values.ordered_by
                        });

                    }

                            } else {

                            // ==============================
                            // NEW ORDER
                            // สั่งอาหารใหม่ → สร้าง Row ใหม่
                            // ==============================

                            doc.meal_history_table.push({
                            meal_date: values.date,
                            breakfast_menu: values.breakfast_menu,
                            lunch_menu: values.lunch_menu,
                            dinner_menu: values.dinner_menu,
                            ordered_by: values.ordered_by
                        });

                    }

                                frappe.call({
                                    method: "frappe.client.save",
                                    args: { doc: doc },
                                    callback: function(save_res) {
                                        if (!save_res.exc) {
                                            // update_ipd_report(frm, values, doc.name, procedure_link_id);
                                            
                                        if (row) {

                                        // =====================================
                                        // EDIT MODE
                                        // อัพเดท Row เดิม
                                        // =====================================

                                        update_existing_order(
                                        frm,
                                        row,
                                        values,
                                        doc.name,
                                        procedure_link_id
                                    );

                                        } else {

                                        // =====================================
                                        // NEW MODE
                                        // เพิ่ม Row ใหม่
                                        // =====================================

                                        update_ipd_report(
                                        frm,
                                        values,
                                        doc.name,
                                        procedure_link_id
                                    );

                                }

                                            // 🟢 ปิด Dialog ทันที และโชว์ Alert สวยๆ แทน msgprint ที่ซ้อนกัน
                                            d.hide();
                                            clear_menu(d);
                                            frappe.show_alert({
                                                message: __('เพิ่มข้อมูลสั่งอาหารเรียบร้อยแล้ว ✅'),
                                                indicator: 'green'
                                            });
                                        }
                                    }
                                });
                            }
                        });
                    } else {
                        frappe.call({
                            method: "frappe.client.insert",
                            args: {
                                doc: {
                                    doctype: "Inpatient Nutrition Data Form",
                                    diet_date: values.date,
                                    ipn_hn_num: values.hn,
                                    ipn_an_num: values.an,
                                    ipn_room_num: values.room_num,
                                    ipn_name: values.name,
                                    age: values.age,
                                    birthdate: values.dob,
                                    ipn_gender: values.gender,
                                    ipn_weight: values.weight,
                                    ipn_high: values.high,
                                    ipn_bmi: values.ipn_bmi,
                                    ipn_bmi_criteria: values.ipn_bmi_criteria,
                                    ipn_suitable_weight: values.ipn_suitable_weight,
                                    ipn_daily_calorie_requirement: values.ipn_daily_calorie_requirement,
                                    ipn_lose_weight: values.ipn_lose_weight,
                                    ipn_gain_weight: values.ipn_gain_weight,
                                    ipn_congenital_disease: (values.congenital_disease || []).map(d => ({ underlying_condition: d })),
                                    diet_breakfast: values.breakfast,
                                    diet_lunch: values.lunch,
                                    diet_dinner: values.dinner,
                                    ipn_breakfast: values.breakfast_menu,
                                    ipn_lunch: values.lunch_menu,
                                    ipn_dinner: values.dinner_menu,
                                    ipn_specify_cancer: values.specify_cancer,
