function toggle_specify_fields(d) {
    let values = d.get_value('congenital_disease') || [];
    let show_cancer = values.includes('มะเร็ง');
    let show_other = values.includes('อื่น ๆ (ระบุ)');

    d.set_df_property('specify_cancer', 'hidden', show_cancer ? 0 : 1);
    d.set_df_property('specify_other', 'hidden', show_other ? 0 : 1);

    if (!show_cancer) { d.set_value('specify_cancer', ''); }
    if (!show_other) { d.set_value('specify_other', ''); }
}

function toggle_food_fields(d) {
    let is_allergic = d.get_value('is_allergic');
    let skip_meal = d.get_value('skip_meal');

    d.set_df_property('specify_allergy', 'hidden', is_allergic ? 0 : 1);
    d.set_df_property('specify_skip', 'hidden', skip_meal ? 0 : 1);

    if (!is_allergic) { d.set_value('specify_allergy', ''); }
    if (!skip_meal) { d.set_value('specify_skip', ''); }
}

function toggle_meal_fields(d) {
    d.set_df_property('breakfast_menu', 'hidden', d.get_value('breakfast') ? 0 : 1);
    d.set_df_property('lunch_menu', 'hidden', d.get_value('lunch') ? 0 : 1);
    d.set_df_property('dinner_menu', 'hidden', d.get_value('dinner') ? 0 : 1);
}

function load_food_menu(d) {
    let procedure = d.get_value('procedure_name');
    let day = d.get_value('thai_day');

    if (!procedure || !day) { return; }

    frappe.db.get_doc('Diet Menu Master', procedure)
    .then(doc => {
        let mode = doc.menu_mode;

        d.set_value('breakfast_menu', '');
        d.set_value('lunch_menu', '');
        d.set_value('dinner_menu', '');

        d.set_df_property('breakfast_menu', 'options', '');
        d.set_df_property('lunch_menu', 'options', '');
        d.set_df_property('dinner_menu', 'options', '');

        d.set_df_property('breakfast_menu', 'hidden', !d.get_value('breakfast'));
        d.set_df_property('lunch_menu', 'hidden', !d.get_value('lunch'));
        d.set_df_property('dinner_menu', 'hidden', !d.get_value('dinner'));

        let selected_meal_set = '';
        if (mode === 'monthly rotation') {
            selected_meal_set = get_monthly_set();
        } else if (mode === 'fixed') {
            selected_meal_set = 'fixed';
        }

        let breakfast_options = [];
        let lunch_options = [];
        let dinner_options = [];

        doc.meal_list.forEach(row => {
            if (row.daily_meal !== day) { return; }

            if (mode === 'monthly rotation') {
                if (row.meal_set !== selected_meal_set) { return; }

                if (d.get_value('breakfast')) {
                    d.set_df_property('breakfast_menu', 'options', row.bf_meal || '');
                    d.set_value('breakfast_menu', row.bf_meal || '');
                }

                if (d.get_value('lunch')) {
                    d.set_df_property('lunch_menu', 'options', row.lh_meal || '');
                    d.set_value('lunch_menu', row.lh_meal || '');
                }

                if (d.get_value('dinner')) {
                    d.set_df_property('dinner_menu', 'options', row.dn_meal || '');
                    d.set_value('dinner_menu', row.dn_meal || '');
                }
            } else if (mode === 'manual select') {
                if (d.get_value('breakfast') && row.bf_meal) {
                    if (!breakfast_options.includes(row.bf_meal)) { breakfast_options.push(row.bf_meal); }
                }

                if (d.get_value('lunch') && row.lh_meal) {
                    if (!lunch_options.includes(row.lh_meal)) { lunch_options.push(row.lh_meal); }
                }

                if (d.get_value('dinner') && row.dn_meal) {
                    if (!dinner_options.includes(row.dn_meal)) { dinner_options.push(row.dn_meal); }
                }
            } else if (mode === 'fixed') {
                if (d.get_value('breakfast')) {
                    d.set_df_property('breakfast_menu', 'options', row.bf_meal || '');
                    d.set_value('breakfast_menu', row.bf_meal || '');
                }

                if (d.get_value('lunch')) {
                    d.set_df_property('lunch_menu', 'options', row.lh_meal || '');
                    d.set_value('lunch_menu', row.lh_meal || '');
                }

                if (d.get_value('dinner')) {
                    d.set_df_property('dinner_menu', 'options', row.dn_meal || '');
                    d.set_value('dinner_menu', row.dn_meal || '');
                }
            }
        });

        if (mode === 'manual select') {
            d.set_df_property('breakfast_menu', 'options', breakfast_options.join('\n'));
            d.set_df_property('lunch_menu', 'options', lunch_options.join('\n'));
            d.set_df_property('dinner_menu', 'options', dinner_options.join('\n'));
        }
    });
}

function get_monthly_set() {
    let today = frappe.datetime.nowdate();
    let month = new Date(today).getMonth() + 1;
    if (month % 2 === 1) { return 'ชุดที่ 1'; }
    return 'ชุดที่ 2';
}

function clear_menu(d) {
    d.set_value("breakfast", 0);
    d.set_value("lunch", 0);
    d.set_value("dinner", 0);

    d.set_value("breakfast_menu", "");
    d.set_value("lunch_menu", "");
    d.set_value("dinner_menu", "");

    let date = d.get_value("date");
    if (date) { load_food_menu(d); }
}

function update_ipd_report(frm, values, nutrition_form, procedure_link_id, existing_row) {

    let row = existing_row;

    if (!row) {
        row = frm.add_child("order_history");
    }

    row.date_pa = values.date;
    row.an_pa = frm.doc.an;
    row.hn_pa = frm.doc.hn;
    row.name_pa = frm.doc.name;

    row.procedure_pa = procedure_link_id;

    row.breakfast_pa = values.breakfast;
    row.breakfast_mn_pa = values.breakfast_menu;

    row.lunch_pa = values.lunch;
    row.lunch_mn_pa = values.lunch_menu;

    row.dinner_pa = values.dinner;
    row.dinner_mn_pa = values.dinner_menu;

    row.name_mn_order = values.ordered_by;
    row.nutrition_form = nutrition_form;

    frm.refresh_field("order_history");

    frm.save();
}

function update_existing_order(frm, row, values, nutrition_form, procedure_link_id) {

    console.log("===== UPDATE EXISTING ORDER =====");
    console.log("ROW:", row);
    console.log("VALUES:", values);
    console.log("NUTRITION FORM:", nutrition_form);

    // ==================================================
    // 1. ต้องมี Row เดิม
    // ==================================================

    if (!row) {

        frappe.msgprint({
            title: "ไม่พบรายการ",
            message: "ไม่พบรายการสั่งอาหารเดิมที่ต้องการแก้ไข",
            indicator: "red"
        });

        return;
    }

    // ==================================================
    // 2. เก็บวันที่เดิมก่อนแก้
    // ==================================================

    let old_date = row.date_pa;

    // ==================================================
    // 3. UPDATE ROW เดิมใน IPD
    // ==================================================

    row.date_pa = values.date;

    row.an_pa = frm.doc.an;
    row.hn_pa = frm.doc.hn;
    row.name_pa = frm.doc.name;

    row.procedure_pa = procedure_link_id;

    row.breakfast_pa = values.breakfast;
    row.breakfast_mn_pa = values.breakfast_menu;

    row.lunch_pa = values.lunch;
    row.lunch_mn_pa = values.lunch_menu;

    row.dinner_pa = values.dinner;
    row.dinner_mn_pa = values.dinner_menu;

    row.name_mn_order = values.ordered_by;

    // ==================================================
    // 4. ทำให้ IPD เป็น Not Saved
    // ==================================================

    frm.dirty();

    frm.refresh_field("order_history");

    // ==================================================
    // 5. ถ้าไม่มี Nutrition Form
    // ==================================================

    if (!nutrition_form) {

        frappe.show_alert({
            message: __("แก้ไขข้อมูลแล้ว กรุณากด Save เพื่อบันทึก"),
            indicator: "green"
        });

        return;
    }

    // ==================================================
    // 6. ดึง Nutrition Form เดิม
    // ==================================================

    frappe.call({

        method: "frappe.client.get",

        args: {
            doctype: "Inpatient Nutrition Data Form",
            name: nutrition_form
        },

        callback: function(res) {

            if (!res.message) {

                frappe.msgprint({
                    title: "ไม่พบข้อมูล",
                    message: "ไม่พบ Inpatient Nutrition Data Form",
                    indicator: "red"
                });

                return;
            }

            let doc = res.message;

            // ==================================================
            // 7. UPDATE Nutrition Form เดิม
            // ==================================================

            doc.diet_date = values.date;

            doc.ipn_get_treat_symptoms = procedure_link_id;

            doc.diet_breakfast = values.breakfast;
            doc.diet_lunch = values.lunch;
            doc.diet_dinner = values.dinner;

            doc.ipn_breakfast = values.breakfast_menu;
            doc.ipn_lunch = values.lunch_menu;
            doc.ipn_dinner = values.dinner_menu;

            doc.ipn_food_allergy = values.ipn_food_allergy;

            doc.diet_special_order = values.special_instruction;

            // ==================================================
            // 8. UPDATE meal_history_table เดิม
            // ==================================================

            doc.meal_history_table = doc.meal_history_table || [];

            let meal_row = doc.meal_history_table.find(function(meal) {

            return meal.meal_date === old_date;

            });

            if (meal_row) {

            // ==========================================
            // แก้ Row เดิม
            // ==========================================

            meal_row.meal_date = values.date;

            meal_row.breakfast_menu = values.breakfast_menu;

            meal_row.lunch_menu = values.lunch_menu;

            meal_row.dinner_menu = values.dinner_menu;

            meal_row.ordered_by = values.ordered_by;

        }

            // ==================================================
            // 9. SAVE Nutrition Form
            // ==================================================

            frappe.call({

                method: "frappe.client.save",

                args: {
                    doc: doc
                },

                callback: function(save_res) {

                    if (save_res.exc) {

                        frappe.msgprint({
                            title: "เกิดข้อผิดพลาด",
                            message: "ไม่สามารถบันทึก Inpatient Nutrition Data Form ได้",
                            indicator: "red"
                        });

                        return;
                    }

                    // ==================================================
                    // 10. ทำให้ IPD เป็น Not Saved
                    // ==================================================

                    frm.dirty();

                    frm.refresh_field("order_history");

                    frappe.show_alert({
                        message: __("แก้ไขข้อมูลแล้ว กรุณากด Save เพื่อบันทึก"),
                        indicator: "green"
                    });

                }

            });

        }

    });

}

