                }
            });

            // Refresh ตาราง
            frm.refresh_field("meal_history_table");

            // โหลดข้อมูล
            load_meal_data(frm, row);
        }

    }

});

function load_meal_data(frm, row) {

    // บันทึกข้อมูลของวันเดิมก่อน
    save_current_assessment(frm);

    frm.set_value("diet_date", row.meal_date);
    frm.set_value("ipn_breakfast", row.breakfast_menu);
    frm.set_value("ipn_lunch", row.lunch_menu);
    frm.set_value("ipn_dinner", row.dinner_menu);

    load_daily_assessment(frm, row.meal_date);

}


function sync_selected_row(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    // อัปเดตเฉพาะ Row ที่ถูกเลือกอยู่
    if (row.select_for_print) {

        load_meal_data(frm, row);

    }

}

function save_current_assessment(frm) {

    let meal_date = frm.doc.diet_date;

    if (!meal_date) return;

    let row = (frm.doc.daily_assessment_table || []).find(r =>
        r.meal_date == meal_date
    );

    if (!row) {

        row = frm.add_child("daily_assessment_table");

        row.meal_date = meal_date;

    }

    row.amount_eat      = frm.doc.ipn_amount_eat;
    row.comment         = frm.doc.ipn_comment;
    row.comment_check   = frm.doc.ipn_comment_check;
    row.date_comment    = frm.doc.ipn_date_comment;
    row.time_comment    = frm.doc.ipn_time_comment;
    row.tranfers        = frm.doc.ipn_data_tranfer;
    row.sign            = frm.doc.ipn_signature;
    row.fullname        = frm.doc.ipn_name_operator;
    row.department      = frm.doc.ipn_position;

    frm.refresh_field("daily_assessment_table");

}

function load_daily_assessment(frm, meal_date) {

    let row = (frm.doc.daily_assessment_table || []).find(r =>
        r.meal_date == meal_date
    );

    // ============================
    // ยังไม่มีข้อมูลของวันนี้
    // ============================

    if (!row) {

        frm.set_value("ipn_amount_eat", "");
        frm.set_value("ipn_comment", "");
        frm.set_value("ipn_comment_check", 0);
        frm.set_value("ipn_date_comment", "");
        frm.set_value("ipn_time_comment", "");
        frm.set_value("ipn_data_tranfer", "");
        frm.set_value("ipn_signature", "");
        frm.set_value("ipn_name_operator", "");
        frm.set_value("ipn_position", "");

        return;

    }

    // ============================
    // มีข้อมูลแล้ว
    // ============================

    frm.set_value("ipn_amount_eat", row.amount_eat || "");
    frm.set_value("ipn_comment", row.comment || "");
    frm.set_value("ipn_comment_check", row.comment_check || 0);

// โหลดวันที่/เวลาเฉพาะเมื่อมีการประเมินจริง
if (row.comment_check) {

    frm.set_value("ipn_date_comment", row.date_comment || "");
    frm.set_value("ipn_time_comment", row.time_comment || "");

} else {

    frm.set_value("ipn_date_comment", "");
    frm.set_value("ipn_time_comment", "");

}

frm.set_value("ipn_data_tranfer", row.tranfers || "");
frm.set_value("ipn_signature", row.sign || "");
frm.set_value("ipn_name_operator", row.fullname || "");
frm.set_value("ipn_position", row.department || "");

}

