frappe.ui.form.on('Inpatient Nutrition Data Form', {
    after_workflow_action: function(frm) {
        setTimeout(() => {
            // เงื่อนไขที่ 1: ร่างเอกสาร
            if (frm.doc.nutri_workflow === "ร่างเอกสาร") {
                update_signature_data(frm, 'name_audit');
            }
            
            // เงื่อนไขที่ 2: อนุมัติ
            else if (frm.doc.nutri_workflow === "อนุมัติ") {
                update_signature_data(frm, 'name_audit');
            }
        }, 500);
    }
});

// ฟังก์ชันกลางเพื่อให้โค้ดดูสะอาดและไม่ซ้ำซ้อน
function update_signature_data(frm, name_field) {
    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'User',
            name: frappe.session.user
        },
        callback: function(response) {
            if (response.message) {
                let full_name = response.message.full_name;
                
                // ใส่ชื่อ
                frm.set_value(name_field, full_name);
                
                // ดึงลายเซ็น
                frappe.call({
                    method: 'frappe.client.get_value',
                    args: {
                        doctype: 'Personnel',
                        filters: { 'fullname': full_name },
                        fieldname: ['fullname']
                    },
                    callback: function(r) {
                        if (r.message && r.message.fullname) {
                            frm.set_value(name_field, r.message.fullname);
                        }
                        frm.save(); // บันทึกข้อมูลหลังจากทำงานเสร็จ
                    }
                });
            }
        }
    });
}

