            { label: 'ชื่อ-นามสกุล', fieldname: 'name', fieldtype: 'Link', 
                options: 'Personnel' },

            { fieldtype: 'Section Break', label: 'ข้อมูลการสั่งอาหาร' },
            { label: 'อาหารเช้า', fieldname: 'breakfast', fieldtype: 'Check', onchange() {toggle_meal_fields(d); load_food_menu(d);} },
            { label: 'เมนูเช้า', fieldname: 'breakfast_menu', fieldtype: 'Data', hidden: 1 },
            { label: 'อาหารเที่ยง', fieldname: 'lunch', fieldtype: 'Check', onchange() {toggle_meal_fields(d); load_food_menu(d);} },
            { label: 'เมนูเที่ยง', fieldname: 'lunch_menu', fieldtype: 'Data', hidden: 1 },
            { label: 'อาหารเย็น', fieldname: 'dinner', fieldtype: 'Check', onchange() {toggle_meal_fields(d); load_food_menu(d);} },
            { label: 'เมนูเย็น', fieldname: 'dinner_menu', fieldtype: 'Data', hidden: 1 },
            { fieldtype: 'Section Break' },
            { label: 'แพ้อาหาร', fieldname: 'is_allergic', fieldtype: 'Check', 
                onchange: function() {
                    toggle_food_fields(d);
                }
            },
            { label: 'โปรดระบุ (แพ้อาหาร)', fieldname: 'specify_allergy', fieldtype: 'Data', hidden: 1 },

            { fieldtype: 'Column Break' },

            { label: 'งดอาหาร', fieldname: 'skip_meal', fieldtype: 'Check',
                onchange: function() {
                    toggle_food_fields(d);
                }
            },
            { label: 'โปรดระบุ (งดอาหาร)', fieldname: 'specify_skip', fieldtype: 'Data', hidden: 1 },

            { fieldtype: 'Section Break' },
            { label: 'คำสั่งพิเศษ', fieldname: 'special_instruction', fieldtype: 'Select', 
                options: ['', 'อาหารฝรั่ง', 'อาหารไทย', 'อาหารอิสลาม', 'อาหารมังสวิรัติ'] },
        ],

        primary_action_label: 'ยืนยันการสั่งอาหาร',

        primary_action(values) {

            let errors = [];

                if (!values.breakfast && !values.lunch && !values.dinner) {
                errors.push("• กรุณาเลือกมื้ออาหารอย่างน้อย 1 มื้อ");
            }

                if (errors.length > 0) {

                frappe.msgprint({
                title: "กรอกข้อมูลไม่ครบ",
                indicator: "red",
                message: errors.join("<br>")
            });

                return;
            }

            // -------------------------
            // รวมข้อมูลแพ้อาหาร / งดอาหาร
            // -------------------------

            let food_summary = [];

            if (values.is_allergic && values.specify_allergy) {
            food_summary.push("แพ้: " + values.specify_allergy);
        }

            if (values.skip_meal && values.specify_skip) {
            food_summary.push("งด: " + values.specify_skip);
        }

        values.ipn_food_allergy = food_summary.join(" / ");

            let meal_history = [{
                meal_date: values.date,
                breakfast_menu: values.breakfast_menu,
                lunch_menu: values.lunch_menu,
                dinner_menu: values.dinner_menu,
                ordered_by: values.ordered_by
            }];

            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Inpatient Nutrition Data Form",
                    filters: {
                        ipn_name: values.name
                    },
                    fields: ["name"],
                    limit_page_length: 1
                },
                callback: function(r) {
                    if (r.message && r.message.length > 0) {
                        let docname = r.message[0].name;
                        frappe.call({
                            method: "frappe.client.get",
                            args: {
                                doctype: "Inpatient Nutrition Data Form",
                                name: docname
                            },
                            callback: function(res) {
                                let doc = res.message;
                                doc.ipn_food_allergy = values.ipn_food_allergy;

                                doc.meal_history_table = doc.meal_history_table || [];
                                doc.meal_history_table.push({
                                    meal_date: values.date,
                                    breakfast_menu: values.breakfast_menu,
                                    lunch_menu: values.lunch_menu,
                                    dinner_menu: values.dinner_menu,
                                    ordered_by: values.ordered_by
                                });

                                frappe.call({
                                        method: "frappe.client.save",
                                        args: { doc: doc },
                                        callback: function(save_res) {
                                        if (!save_res.exc) {

                                        frappe.msgprint({
                                        title: "สำเร็จ",
                                        message: "เพิ่มข้อมูลเรียบร้อยแล้ว ✅",
                                        indicator: "green",
                                        primary_action: {
                                        label: "OK", 
                                        action() {
                                        clear_menu(d);

                                    // ปิด Popup
                                    frappe.hide_msgprint();
                                }
                            }
                        });


    }
}
                                });
                            }
                        });
                    } else {
                        frappe.call({
                            method: "frappe.client.insert",
                            args: {
                                doc: {
                                    doctype: "Inpatient Nutrition Data Form",
                                    diet_date: values.date,
                                    ipn_room_num: values.room_num,
                                    ipn_name: values.name,
                                    ipn_gender: values.gender,
                                    ipn_congenital_disease: (values.congenital_disease || []).map(d => {
                                        return {
                                            underlying_condition: d
                                        };
                                    }),
                                    diet_breakfast: values.breakfast,
                                    diet_lunch: values.lunch,
                                    diet_dinner: values.dinner,
                                    ipn_breakfast: values.breakfast_menu,
                                    ipn_lunch: values.lunch_menu,
                                    ipn_dinner: values.dinner_menu,
                                    ipn_specify_cancer: values.specify_cancer,
                                    ipn_specify_other: values.specify_other,
                                    diet_food_allergy: values.is_allergic,
                                    diet_food_allergy_option: values.specify_allergy,
                                    diet_no_food: values.skip_meal,
                                    diet_no_food_detail: values.specify_skip,
                                    ipn_food_allergy: values.ipn_food_allergy,
                                    diet_special_order: values.special_instruction,
                                    name_order: values.ordered_by,
                                    meal_history_table: meal_history
                                }
                            },
                            callback: function(insert_res) {
    if (!insert_res.exc) {

        frappe.msgprint({
            title: "สำเร็จ",
            message: "บันทึกข้อมูลเรียบร้อยแล้ว ✅",
            indicator: "green",
            primary_action: {
                label: "OK",
                action() {
                    clear_menu(d);

                // ปิด Popup
                frappe.hide_msgprint();
                }
            }
        });

    }
}
                        });
                    }
                }
            });
        }
    });

    let today = frappe.datetime.nowdate();
    let day_names = [
        "วันอาทิตย์", "วันจันทร์", "วันอังคาร", "วันพุธ", "วันพฤหัสบดี", "วันศุกร์", "วันเสาร์"
    ];
    let js_date = new Date(today);
    let thai_day = day_names[js_date.getDay()];
    d.set_value('thai_day', thai_day);

    d.show();

    d.get_primary_btn().css({
        'background-color': '#198754',
        'border-color': '#198754',
        'font-size': '16px',
        'font-weight': 'bold',
        'padding': '12px 20px',
        'border-radius': '12px',
        'box-shadow': '0 4px 10px rgba(0,0,0,0.15)'
    });

    d.$wrapper.find('.modal-header').css({
        'border-bottom': 'none',
        'padding-bottom': '0px'
    });

    d.$wrapper.find('.modal-title').hide();

    // เพิ่มระยะด้านบน content
    d.$wrapper.find('.modal-body').css({
        'padding-top': '30px'
    });

    toggle_specify_fields(d);
    toggle_food_fields(d);
    toggle_meal_fields(d);
}

function toggle_food_fields(d) {
    let is_allergic = d.get_value('is_allergic'); // 1 หรือ 0
    let skip_meal = d.get_value('skip_meal');     // 1 หรือ 0

    // แสดง / ซ่อน
    d.set_df_property('specify_allergy', 'hidden', is_allergic ? 0 : 1);
    d.set_df_property('specify_skip', 'hidden', skip_meal ? 0 : 1);

    // เคลียร์ค่า
    if (!is_allergic) {
        d.set_value('specify_allergy', '');
    }
    if (!skip_meal) {
        d.set_value('specify_skip', '');
    }
}

function toggle_meal_fields(d) {
    d.set_df_property(
        'breakfast_menu',
        'hidden',
        d.get_value('breakfast') ? 0 : 1
    );

    d.set_df_property(
        'lunch_menu',
        'hidden',
        d.get_value('lunch') ? 0 : 1
    );

    d.set_df_property(
        'dinner_menu',
        'hidden',
        d.get_value('dinner') ? 0 : 1
    );
}

function clear_menu(d) {

    d.set_value("breakfast", 0);
    d.set_value("lunch", 0);
    d.set_value("dinner", 0);

    d.set_value("breakfast_menu", "");
    d.set_value("lunch_menu", "");
    d.set_value("dinner_menu", "");
}
